from collections import deque

# Graph represented as an adjacency list
graph = {
    "A": ["B", "C"],
    "B": ["D", "E"],
    "C": ["F"],
    "D": [],
    "E": ["F"],
    "F": [],
}

def bfs(graph, start, goal):
    """Breadth-First Search: explores level by level."""
    queue = deque([(start, [start])])
    visited = {start}

    while queue:
        node, path = queue.popleft()
        if node == goal:
            return path
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))
    return None

def dfs(graph, start, goal):
    """Depth-First Search: explores one branch before backtracking."""
    stack = [(start, [start])]
    visited = set()

    while stack:
        node, path = stack.pop()
        if node == goal:
            return path
        if node in visited:
            continue
        visited.add(node)
        # Reverse to visit neighbors in their listed order.
        for neighbor in reversed(graph.get(node, [])):
            if neighbor not in visited:
                stack.append((neighbor, path + [neighbor]))
    return None

def main():
    print("Graph:", graph)
    start = input("Enter start node (A-F): ").strip().upper()
    goal = input("Enter goal node (A-F): ").strip().upper()
    if start not in graph or goal not in graph:
        print("Invalid node. Choose a node from A, B, C, D, E, F.")
        return

    print("BFS path:", " -> ".join(bfs(graph, start, goal) or []) or "No path found")
    print("DFS path:", " -> ".join(dfs(graph, start, goal) or []) or "No path found")

if __name__ == "__main__":
    main()

import heapq
from itertools import count

GOAL = (1, 2, 3, 4, 5, 6, 7, 8, 0)  # 0 represents the blank tile

def manhattan(state):
    """Sum of Manhattan distances from each tile to its goal position."""
    distance = 0
    for index, tile in enumerate(state):
        if tile == 0:
            continue
        goal_index = tile - 1
        row, col = divmod(index, 3)
        goal_row, goal_col = divmod(goal_index, 3)
        distance += abs(row - goal_row) + abs(col - goal_col)
    return distance

def neighbors(state):
    blank = state.index(0)
    row, col = divmod(blank, 3)
    possible = []
    if row > 0: possible.append(blank - 3)
    if row < 2: possible.append(blank + 3)
    if col > 0: possible.append(blank - 1)
    if col < 2: possible.append(blank + 1)
    for target in possible:
        board = list(state)
        board[blank], board[target] = board[target], board[blank]
        yield tuple(board)

def is_solvable(state):
    values = [x for x in state if x != 0]
    inversions = sum(values[i] > values[j]
                     for i in range(len(values))
                     for j in range(i + 1, len(values)))
    return inversions % 2 == 0

def astar(start):
    """Return a sequence of states from start to goal, or None."""
    if not is_solvable(start):
        return None
    tie_breaker = count()
    frontier = [(manhattan(start), 0, next(tie_breaker), start)]
    parent = {start: None}
    best_g = {start: 0}

    while frontier:
        _, g, _, current = heapq.heappop(frontier)
        if g != best_g.get(current):
            continue
        if current == GOAL:
            path = []
            while current is not None:
                path.append(current)
                current = parent[current]
            return path[::-1]

        for nxt in neighbors(current):
            new_g = g + 1
            if new_g < best_g.get(nxt, float("inf")):
                best_g[nxt] = new_g
                parent[nxt] = current
                heapq.heappush(frontier,
                               (new_g + manhattan(nxt), new_g,
                                next(tie_breaker), nxt))
    return None

def print_board(state):
    for i in range(0, 9, 3):
        print(" ".join("_" if x == 0 else str(x) for x in state[i:i+3]))
    print()

def main():
    print("Enter the 8-puzzle tiles row by row; use 0 for the blank.")
    try:
        values = [int(x) for x in input("Enter 9 numbers separated by spaces: ").split()]
    except ValueError:
        print("Please enter integers only.")
        return
    if len(values) != 9 or set(values) != set(range(9)):
        print("Input must contain each number from 0 to 8 exactly once.")
        return

    path = astar(tuple(values))
    if path is None:
        print("This puzzle is unsolvable.")
        return
    print(f"Solution found in {len(path) - 1} moves:
")
    for step, state in enumerate(path):
        print(f"Step {step}:")
        print_board(state)

if __name__ == "__main__":
    main()

# Minimax for Tic-Tac-Toe (X is the maximizing player, O is minimizing)
HUMAN = "O"
AI = "X"
EMPTY = " "

WIN_LINES = (
    (0, 1, 2), (3, 4, 5), (6, 7, 8),
    (0, 3, 6), (1, 4, 7), (2, 5, 8),
    (0, 4, 8), (2, 4, 6),
)

def winner(board):
    for a, b, c in WIN_LINES:
        if board[a] != EMPTY and board[a] == board[b] == board[c]:
            return board[a]
    return None

def available_moves(board):
    return [i for i, cell in enumerate(board) if cell == EMPTY]

def minimax(board, is_maximizing, depth=0):
    result = winner(board)
    if result == AI:
        return 10 - depth, None
    if result == HUMAN:
        return depth - 10, None
    moves = available_moves(board)
    if not moves:
        return 0, None

    best_move = None
    if is_maximizing:
        best_score = float("-inf")
        for move in moves:
            board[move] = AI
            score, _ = minimax(board, False, depth + 1)
            board[move] = EMPTY
            if score > best_score:
                best_score, best_move = score, move
        return best_score, best_move

    best_score = float("inf")
    for move in moves:
        board[move] = HUMAN
        score, _ = minimax(board, True, depth + 1)
        board[move] = EMPTY
        if score < best_score:
            best_score, best_move = score, move
    return best_score, best_move

def print_board(board):
    cells = [str(i + 1) if value == EMPTY else value
             for i, value in enumerate(board)]
    for row in range(0, 9, 3):
        print(" | ".join(cells[row:row + 3]))
        if row < 6:
            print("---------")
    print()

def main():
    board = [EMPTY] * 9
    print("Tic-Tac-Toe: you are O, AI is X. Choose positions 1-9.")
    while True:
        print_board(board)
        try:
            move = int(input("Your move (1-9): ")) - 1
        except ValueError:
            print("Please enter a number from 1 to 9.")
            continue
        if move not in range(9) or board[move] != EMPTY:
            print("That position is not available. Try again.")
            continue
        board[move] = HUMAN
        if winner(board) == HUMAN:
            print_board(board)
            print("You win!")
            break
        if not available_moves(board):
            print_board(board)
            print("It's a draw!")
            break

        _, ai_move = minimax(board, True)
        board[ai_move] = AI
        print("AI chooses position", ai_move + 1)
        if winner(board) == AI:
            print_board(board)
            print("AI wins!")
            break
        if not available_moves(board):
            print_board(board)
            print("It's a draw!")
            break

if __name__ == "__main__":
    main()
